#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry classical_sets. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam2011A2. Variable R : realType. Variables A B C M D : 'rV[R]_2. Hypothesis triangle_ABC : collinear_rV3 A B C = false. Hypothesis isosceles_ABC : dist A B = dist A C. Hypothesis M_on_BC : M \is_between B C. Hypothesis AM_perp_BC : (<[A, M]> - <[B, C]>) = 0. Hypothesis AM_altitude : dist A M = 11. Hypothesis D_on_AM : D \is_between A M. Hypothesis AD_length : dist A D = 10. Hypothesis angle_BDC_3x : exists alpha : R, 0 < alpha < PI/2 /\ (\angle_rV B D C = 3 * (\angle_rV B A C)). Theorem putnam_2011_a2 : exists a b : nat, (forall P : R, (exists x : R, 0 < x) -> (perimeter_rV A B C = a%:R + sqrt b%:R)) /\ a + b = 616. Proof. Admitted. End
